import React, { useState, useEffect } from 'react';
import axios from 'axios';
import styled from 'styled-components';

// Styled Components for the page
const PageContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  margin: 20px;
  font-family: 'Arial', sans-serif;
`;

const Title = styled.h1`
  font-size: 2rem;
  color: #2c3e50;
  margin-bottom: 20px;
`;

const EmployeeFormContainer = styled.div`
  width: 100%;
  max-width: 600px;
  background: #ecf0f1;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
  margin-bottom: 30px;
`;

const FormTitle = styled.h2`
  font-size: 1.5rem;
  color: #34495e;
  margin-bottom: 20px;
`;

const FormInput = styled.input`
  width: 100%;
  padding: 12px;
  margin: 8px 0;
  border: 1px solid #bdc3c7;
  border-radius: 4px;
  font-size: 1rem;
  color: #2c3e50;

  &:focus {
    outline: none;
    border-color: #3498db;
  }
`;

const FormButton = styled.button`
  width: 100%;
  padding: 12px;
  background-color: #3498db;
  color: white;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
  cursor: pointer;
  margin-top: 20px;

  &:hover {
    background-color: #2980b9;
  }
`;

const EmployeeTable = styled.table`
  width: 100%;
  max-width: 1000px;
  margin-top: 30px;
  border-collapse: collapse;
`;

const TableHeader = styled.th`
  padding: 12px;
  background-color: #2c3e50;
  color: white;
  font-size: 1rem;
  text-align: left;
  border-top: 1px solid #ddd;
  border-bottom: 1px solid #ddd;
`;

const TableRow = styled.tr`
  &:hover {
    background-color: #f4f4f4;
  }
`;

const TableData = styled.td`
  padding: 12px;
  border-bottom: 1px solid #ddd;
  font-size: 1rem;
`;

const ActionButton = styled.button`
  padding: 6px 12px;
  background-color: #3498db;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;

  &:hover {
    background-color: #2980b9;
  }

  margin-right: 10px;
`;

const ErrorMessage = styled.div`
  color: red;
  font-size: 1rem;
  margin-top: 10px;
`;

// EmployeePage Component
const EmployeePage = () => {
  const [employees, setEmployees] = useState([]);
  const [newEmployee, setNewEmployee] = useState({
    name: '',
    role: '',
    fixedSalary: '',
    salaryPerDay: '',
    daysWorked: '',
    expense: ''
  });
  const [error, setError] = useState(null);
  const [showAddEmployeeForm, setShowAddEmployeeForm] = useState(false);

  const fetchEmployees = () => {
    axios.get('http://localhost:5001/api/employees/ABC123') // Update with dynamic lorry registration
      .then((response) => {
        setEmployees(response.data.employees);
      })
      .catch((error) => {
        console.error('Error fetching employees:', error);
      });
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewEmployee((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!newEmployee.name || !newEmployee.role) {
      setError('Name and Role are required.');
      return;
    }

    axios.post('http://localhost:5001/api/employees/ABC123', newEmployee) // Update with dynamic lorry registration
      .then((response) => {
        setEmployees((prev) => [...prev, response.data]);
        setShowAddEmployeeForm(false);
        setNewEmployee({
          name: '',
          role: '',
          fixedSalary: '',
          salaryPerDay: '',
          daysWorked: '',
          expense: ''
        });
        setError(null);
      })
      .catch((error) => {
        console.error('Error adding employee:', error);
        setError('Failed to add employee. Please try again later.');
      });
  };

  const updateSalary = (employeeId, updatedSalary) => {
    axios.put(`http://localhost:5001/api/employees/${employeeId}`, updatedSalary)
      .then((response) => {
        setEmployees((prev) =>
          prev.map((emp) => (emp.id === employeeId ? { ...emp, ...updatedSalary } : emp))
        );
      })
      .catch((error) => {
        console.error('Error updating salary:', error);
      });
  };

  const deleteEmployee = (employeeId) => {
    axios.delete(`http://localhost:5001/api/employees/${employeeId}`)
      .then((response) => {
        setEmployees((prev) => prev.filter((emp) => emp.id !== employeeId));
      })
      .catch((error) => {
        console.error('Error deleting employee:', error);
      });
  };

  useEffect(() => {
    fetchEmployees();
  }, []);

  return (
    <PageContainer>
      <Title>Employee Management</Title>

      {/* Add Employee Form */}
      {showAddEmployeeForm ? (
        <EmployeeFormContainer>
          <FormTitle>Add New Employee</FormTitle>
          <form onSubmit={handleSubmit}>
            <FormInput
              type="text"
              name="name"
              value={newEmployee.name}
              placeholder="Name"
              onChange={handleInputChange}
            />
            <FormInput
              type="text"
              name="role"
              value={newEmployee.role}
              placeholder="Role"
              onChange={handleInputChange}
            />
            <FormInput
              type="number"
              name="fixedSalary"
              value={newEmployee.fixedSalary}
              placeholder="Fixed Salary"
              onChange={handleInputChange}
            />
            <FormInput
              type="number"
              name="salaryPerDay"
              value={newEmployee.salaryPerDay}
              placeholder="Salary Per Day"
              onChange={handleInputChange}
            />
            <FormInput
              type="number"
              name="daysWorked"
              value={newEmployee.daysWorked}
              placeholder="Days Worked"
              onChange={handleInputChange}
            />
            <FormInput
              type="number"
              name="expense"
              value={newEmployee.expense}
              placeholder="Expense"
              onChange={handleInputChange}
            />
            <FormButton type="submit">Add Employee</FormButton>
            {error && <ErrorMessage>{error}</ErrorMessage>}
          </form>
        </EmployeeFormContainer>
      ) : (
        <FormButton onClick={() => setShowAddEmployeeForm(true)}>Add Employee</FormButton>
      )}

      {/* Employees Table */}
      <EmployeeTable>
        <thead>
          <tr>
            <TableHeader>Name</TableHeader>
            <TableHeader>Role</TableHeader>
            <TableHeader>Fixed Salary</TableHeader>
            <TableHeader>Salary Per Day</TableHeader>
            <TableHeader>Days Worked</TableHeader>
            <TableHeader>Expense</TableHeader>
            <TableHeader>Actions</TableHeader>
          </tr>
        </thead>
        <tbody>
          {employees.map((employee) => (
            <TableRow key={employee.id}>
              <TableData>{employee.name}</TableData>
              <TableData>{employee.role}</TableData>
              <TableData>{employee.fixed_salary}</TableData>
              <TableData>{employee.salary_per_day}</TableData>
              <TableData>{employee.days_worked}</TableData>
              <TableData>{employee.expense}</TableData>
              <TableData>
                <ActionButton onClick={() => updateSalary(employee.id, { fixedSalary: 50000, salaryPerDay: 1000 })}>
                  Update Salary
                </ActionButton>
                <ActionButton onClick={() => deleteEmployee(employee.id)}>Delete</ActionButton>
              </TableData>
            </TableRow>
          ))}
        </tbody>
      </EmployeeTable>
    </PageContainer>
  );
};

export default EmployeePage;
